+//
+// Each block of K elements builds a short local prefix chain; the running carry
+// is then added to every position of the block, so between blocks only one
+// carry dependency remains (no tree sum, no serial subtraction chain). K
+// position-indexed sub-histograms break the read-modify-write chain on hot
+// bins: consecutive elements of a block increment K different counters.
+constexpr size_t K = 8;
+
+extern "C" void scan_and_histogram(const int64_t* __restrict__ in, int64_t* __restrict__ out, size_t n, uint64_t* __restrict__ hist) {
+    uint32_t sub[K][256] = {};
+
+    size_t i = 0;
+    int64_t carry = 0;
+    for (; i + K <= n; i += K) {
+        if (i + 4 * K < n) {
+            __builtin_prefetch(in + i + 2 * K, 0, 3);
+            __builtin_prefetch(out + i + 2 * K, 0, 3);
+        }
+
+        int64_t x[K];
+        #pragma unroll
+        for (size_t k = 0; k < K; ++k) x[k] = in[i + k];
+
+        int64_t p = x[0];
+        out[i] = carry + p;
+        sub[0][(unsigned)x[0] & 255u]++;
+        #pragma unroll
+        for (size_t k = 1; k < K; ++k) {
+            p += x[k];
+            out[i + k] = carry + p;
+            sub[k][(unsigned)x[k] & 255u]++;
+        }
+        carry += p;
+    }
+    int64_t sum = carry;
+    for (; i < n; ++i) {
+        int64_t x = in[i];
+        sum += x;
         out[i] = sum;
-        hist[in[i] & 255]++;
+        sub[i & (K - 1)][(unsigned)x & 255u]++;
+    }
+    for (int b = 0; b < 256; ++b) {
+        uint64_t total = 0;
+        for (size_t k = 0; k < K; ++k) total += (uint64_t)sub[k][b];
+        hist[b] = total;
     }
 }
